/**
 * Corpus de demostración para trabajar sin API.
 *
 * Son obras y autores reales, todas de dominio público. Cada pasaje se ha
 * copiado de forma automática, sin retocar, de la edición digital indicada
 * junto a cada obra, con su ortografía de origen (la «ſ» del Quijote de 1608,
 * los acentos de las ediciones del siglo XIX, el inglés de Bentham). Nadie
 * aparece diciendo nada que no dijera o escribiera.
 *
 * Lo que sí es de la demo: la unidad N de cada documento muestra el pasaje N,
 * y los números de página («p. 23») son los de la copia en PDF de la edición
 * digital que tiene la demo, no los folios de ninguna edición impresa
 * histórica. En el audio y el vídeo, los minutos se estiman en proporción a la
 * longitud del texto (la demo no alinea la grabación). Los pasajes son una
 * selección: en las obras largas se saltan capítulos enteros.
 */
import type { Ancla, MetadatosDocumento, TipoEntrada } from '@scholaris/nucleo';
