export interface DocDemo {
  id: string;
  tipo: TipoEntrada;
  meta: MetadatosDocumento;
  unidades: number;
  duracion?: number;
  /** Segundos del medio que cubre la transcripción, si no es el medio entero. */
  cubre?: number;
  /** Preliminares con folio romano (solo libros). */
  romanas?: number;
  /** Páginas sin folio al principio (portadillas). */
  sinFolio?: number;
  /** Folios deducidos con poca confianza: desde-hasta (físicas). */
  dudosas?: [number, number];
  secciones: Array<{ titulo: string; nivel: number; unidad: number }>;
  /** Pasajes literales, en orden: la unidad N muestra el pasaje N. */
  pasajes: string[];
  /** El texto de la página ya trae sus títulos (facsímiles): no se añaden encabezados. */
  sinEncabezados?: boolean;
  /** Audio y vídeo: quién habla al empezar cada unidad. */
  turnos?: string[];
  /** Ilustraciones reales de la obra, con su unidad. */
  figuras?: Array<{ unidad: number; pie: string }>;
  bibliotecas: string[];
  creado: string;
  bytes: number;
  mime: string;
  hablantes?: string[];
}

