function hash(t: string) {
  let h = 2166136261;
  for (let i = 0; i < t.length; i++) h = Math.imul(h ^ t.charCodeAt(i), 16777619);
  return h >>> 0;
}

/** Tiempos de cada unidad, en proporción a la longitud de su texto. */
function tiempos(d: DocDemo, orden: number): [number, number] {
  const total = d.cubre ?? d.duracion ?? 60;
  if (d.pasajes.length !== d.unidades) {
    const paso = total / d.unidades;
    return [Math.round((orden - 1) * paso), Math.round(orden * paso)];
  }
  const largos = d.pasajes.map((p) => p.replace(/\*\*[^*\n]+:\*\*\s*/g, '').length);
  const suma = largos.reduce((s, n) => s + n, 0) || 1;
  const hasta = (n: number) => largos.slice(0, n).reduce((s, x) => s + x, 0);
  return [Math.round((total * hasta(orden - 1)) / suma), Math.round((total * hasta(orden)) / suma)];
}

export function anclaDe(d: DocDemo, orden: number): Ancla {
  switch (d.tipo) {
    case 'pdf': case 'pdf_escaneado': case 'fotos': {
      const sin = d.sinFolio ?? 0, rom = d.romanas ?? 0;
      let impresa: string | null = null, romana = false;
      if (orden > sin && orden <= sin + rom) { impresa = aRomano(orden - sin); romana = true; }
      else if (orden > sin + rom) impresa = String(orden - sin - rom);
      const dudosa = d.dudosas && orden >= d.dudosas[0] && orden <= d.dudosas[1];
      return { tipo: 'pagina', fisica: orden, impresa, romana, origen: impresa ? (dudosa ? 'deducido' : 'leido') : 'ninguno', confianza: dudosa ? 0.58 : impresa ? 0.97 : 1 };
    }
    case 'audio': case 'video': {
      const [t0, t1] = tiempos(d, orden);
      const hablante = d.turnos?.[orden - 1] ?? d.hablantes?.[0];
      return { tipo: 'tiempo', t0, t1, ...(hablante ? { hablante } : {}) };
    }
    case 'epub': {
      const sec = [...d.secciones].reverse().find((s) => s.unidad <= orden);
      return { tipo: 'seccion', ruta: [sec?.titulo ?? d.meta.titulo], parrafo: orden - (sec?.unidad ?? 1) + 1 };
    }
    case 'presentacion': return { tipo: 'diapositiva', n: orden };
    case 'hoja': return { tipo: 'hoja', hoja: 'Hoja 1', filaDesde: (orden - 1) * 50 + 1, filaHasta: orden * 50 };
    case 'web': {
      const sec = [...d.secciones].reverse().find((s) => s.unidad <= orden);
      return { tipo: 'web', url: d.meta.url ?? '', ruta: [sec?.titulo ?? ''], parrafo: orden, consultada: '2026-10-07' };
    }
    default: return { tipo: 'imagen' };
  }
}

/** Texto de una unidad: su pasaje literal, con el título de la sección si empieza en ella. */
export function textoDe(d: DocDemo, orden: number): string {
  const pasaje = d.pasajes.length ? (d.pasajes[(orden - 1) % d.pasajes.length] as string) : '';
  if (d.sinEncabezados || d.tipo === 'audio' || d.tipo === 'video') return pasaje;
  const titulo = d.secciones.find((s) => s.unidad === orden);
  return (titulo ? `## ${titulo.titulo}\n\n` : '') + pasaje;
}

export function portadaColor(d: DocDemo): string {
  const colores = ['#b8321c', '#23457a', '#e2a52a', '#22160f', '#4f6f33'];
  return colores[hash(d.id) % colores.length] as string;
}
